const norm=s=>String(s).trim().replace(/\s+/g,' ');
let livros=[],revs={};
const lista=document.getElementById('lista'),filtro=document.getElementById('filtro'),erro=document.getElementById('erro'),status=document.getElementById('status');
async function carregar(){
  const r=await tessera.call('data.read',{});
  livros=r.data.books||[];revs=(r.revisions&&r.revisions.books)||{};
  desenhar();
}
function opcoes(){
  const atual=filtro.value;const vistos=[];
  for(const b of livros){const g=norm(b.genre);if(g&&!vistos.includes(g))vistos.push(g);}
  vistos.sort((a,b)=>a.localeCompare(b,'pt-BR'));
  filtro.textContent='';
  const o0=document.createElement('option');o0.value='';o0.textContent='Todos os gêneros';filtro.appendChild(o0);
  for(const g of vistos){const o=document.createElement('option');o.value=g;o.textContent=g;filtro.appendChild(o);}
  filtro.value=vistos.includes(atual)?atual:'';
}
function desenhar(){
  opcoes();
  const f=norm(filtro.value);
  lista.textContent='';
  let n=0;
  for(const b of livros){
    if(f&&norm(b.genre)!==f)continue;
    n++;
    const li=document.createElement('li');li.setAttribute('data-hook','item');
    const t=document.createElement('span');t.className='t';t.textContent=b.title;li.appendChild(t);
    if(b.example){const e=document.createElement('span');e.className='ex';e.setAttribute('data-example','');e.textContent='Exemplo';li.appendChild(e);}
    const g=document.createElement('span');g.className='g';g.setAttribute('data-hook','category');g.textContent=b.genre;li.appendChild(g);
    const w=document.createElement('span');w.className='n';
    const id='n-'+b.id;
    const l=document.createElement('label');l.setAttribute('for',id);l.textContent='Nota';
    const s=document.createElement('select');s.id=id;s.setAttribute('aria-label','Nota de '+b.title);
    for(let i=1;i<=5;i++){const o=document.createElement('option');o.value=String(i);o.textContent=String(i);s.appendChild(o);}
    s.value=String(b.rating);
    s.addEventListener('change',()=>mudarNota(b.id,Number(s.value)));
    w.appendChild(l);w.appendChild(s);li.appendChild(w);
    const rm=document.createElement('button');rm.type='button';rm.className='sec';rm.setAttribute('data-hook','item-remove');rm.textContent='Remover';rm.setAttribute('aria-label','Remover '+b.title);
    rm.addEventListener('click',()=>remover(b.id));
    li.appendChild(rm);lista.appendChild(li);
  }
  status.textContent=livros.length===0?'Nenhum livro na lista ainda. Adicione o primeiro acima.':(n===0?'Nenhum livro neste gênero.':'');
}
async function operar(ops,msg){
  try{await tessera.call('data.patch',{operations:ops});await carregar();erro.textContent='';status.textContent=msg||status.textContent;}
  catch(e){erro.textContent='Não foi possível salvar a alteração. Tente de novo.';}
}
function remover(id){operar([{op:'remove',collection:'books',id,revisionCount:revs[id]}]);}
function mudarNota(id,v){operar([{op:'replace',collection:'books',id,revisionCount:revs[id],fields:{rating:v,example:false}}]);}
async function adicionar(){
  const nome=document.getElementById('nome'),gen=document.getElementById('genero'),nota=document.getElementById('nota');
  const t=nome.value.trim(),g=gen.value.trim();
  if(!t||!g){erro.textContent=!t?'Digite o título do livro.':'Digite o gênero do livro.';return;}
  try{
    await tessera.call('data.patch',{operations:[{op:'add',collection:'books',record:{title:t,genre:g,rating:Number(nota.value),example:false}}]});
    nome.value='';gen.value='';erro.textContent='';
    await carregar();nome.focus();
  }catch(e){erro.textContent='Não foi possível salvar o livro. O que você digitou foi mantido.';}
}
document.getElementById('add').addEventListener('click',adicionar);
for(const id of ['nome','genero']){document.getElementById(id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();adicionar();}});}
filtro.addEventListener('change',desenhar);
carregar().catch(()=>{status.textContent='Não foi possível carregar a lista.';});
